-- SINH TỰ ĐỘNG từ src/lib/content — không sửa tay. Sửa nội dung trong file nguồn rồi sinh lại.
-- Nạp bài tập Lớp 2, Học kì 2 (Toán, Tiếng Việt: Kết nối tri thức; Tiếng Anh: Global Success) — câu soạn sẵn của từng bài.
-- Yêu cầu: đã chạy migration 0001 → 0008, đã có ít nhất 1 tài khoản system_admin và ĐÃ NẠP supabase/seed/curriculum_grade2.sql.
-- Bài đã nạp từ lần trước (cùng seed_id) được bỏ qua, chỉ thêm bài mới.

-- Bài 37 · Bài 37. Phép nhân (8 câu)
do $$
declare v_admin uuid; v_lesson uuid; v_q uuid;
begin
  select user_id into v_admin from public.user_roles where role = 'system_admin' order by created_at limit 1;
  if v_admin is null then raise exception 'Cần có ít nhất 1 tài khoản system_admin trước khi nạp bài tập'; end if;
  if exists (select 1 from public.lessons where content ->> 'seed_id' = 'toan2-kntt-b37') then return; end if;
  select s.id, 'Bài 37. Phép nhân', '{"seed_id":"toan2-kntt-b37","kind":"book","book":"Kết nối tri thức","ref":"Bài 37","unit_code":"KNTT.T2.CD8","unit_title":"Chủ đề 8. Phép nhân, phép chia","description":"Phép nhân là cộng các số hạng bằng nhau."}'::jsonb, 'review', v_admin, 'Kết nối tri thức', 2, 67, (select id from public.curriculum_topics where code = 'T2.NC')
  from public.subjects s where s.code = 'toan-2' returning id into v_lesson;
end $$;

