  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'matching', '{"text":"Nối câu hỏi với câu trả lời phù hợp.","left":["What do you want?","Pass me the juice, please.","What can you see?"]}'::jsonb, '["I want some yo-yos.","Here you are.","I can see a rainbow."]'::jsonb, null, 5, 90, 8, 'draft', (select id from public.exercise_forms where code = 'TA.HOIDAP'), (select id from public.learning_outcomes where code = 'A2.CAU.01')) returning id into v_q;
  insert into public.question_keys (question_id, answer_key, explanation, solution) values (v_q, '{"pairs":{"Pass me the juice, please.":"Here you are.","What do you want?":"I want some yo-yos.","What can you see?":"I can see a rainbow."}}'::jsonb, '{"text":"Pass me the juice, please. – Here you are.; What do you want? – I want some yo-yos.; What can you see? – I can see a rainbow."}'::jsonb, '{"text":"\"Pass me the juice, please.\" → \"Here you are.\" (Làm ơn đưa tớ nước ép. – Của bạn đây.); \"What do you want?\" → \"I want some yo-yos.\" (Bạn muốn gì? – Tớ muốn con quay yo-yo.); \"What can you see?\" → \"I can see a rainbow.\" (Bạn nhìn thấy gì? – Tớ nhìn thấy cầu vồng.)"}'::jsonb);
